    localStorage.setItem('ψ_last_config', raw);
  } catch(e) {
    console.error('[ψ-config-error]', e);
  }
}

function diffObjects(a, b, path = '') {
  const changes = {};
  for (const key in b) {
    if (!(key in a)) {
      changes[`+ ${path}${key}`] = b[key];
    } else if (JSON.stringify(a[key]) !== JSON.stringify(b[key])) {
      if (typeof b[key] === 'object' && b[key] !== null) {
        Object.assign(changes, diffObjects(a[key], b[key], `${path}${key}.`));
      } else {
        changes[`~ ${path}${key}`] = { old: a[key], new: b[key] };
      }
    }
  }
  return changes;
}

