/**
 * @file agent.js
 * @description The core logic for the Project Chimera autonomous agent.
 */

const TaskQueue = require('./task_queue');
const { generateResponse } = require('./llm_handler');
const { executeTool } = require('./tool_executor');
const CONFIG = require('./config');

class AutonomousAgent {
    constructor(missionObjective) {
        this.mission = missionObjective;
        this.taskQueue = new TaskQueue();
        this.contextHistory = [];
        this.loopCount = 0;
    }

    /**
     * Parses the LLM's text response to find a tool call block.
     * @param {string} responseText The text from the LLM.
     * @returns {object|null} A parsed tool call object or null if not found.
     */
    parseForToolCall(responseText) {
        const match = responseText.match(/<tool_call>([\s\S]*?)<\/tool_call>/);
        if (match && match[1]) {
            try {
                // The LLM might output slightly malformed JSON, so we clean it up.
                const cleanJsonString = match[1].trim().replace(/```json\n?/, '').replace(/```$/, '');
                return JSON.parse(cleanJsonString);
            } catch (e) {
                console.error(`[AGENT_ERROR] Failed to parse tool call JSON: ${e.message}`);
                return null;
            }
        }
        return null;
    }

    /**
     * The main execution loop of the agent.
     */
    async run() {
        console.log(`[AGENT_SYSTEM] Mission briefing received: "${this.mission}"`);
        this.taskQueue.addTask({ 
            id: 1, 
            description: `The overall mission is: "${this.mission}". Your first task is to create a step-by-step plan to achieve this.`
        });

        while (!this.taskQueue.isEmpty() && this.loopCount < CONFIG.AGENT_MAX_LOOPS) {
            this.loopCount++;
            const currentTask = this.taskQueue.getNextTask();

            console.log(`\n--- [Loop ${this.loopCount}] ---`);
            console.log(`[AGENT_TASK] Executing: ${currentTask.description}`);

            // 1. Generate a response from the LLM based on the current task and context.
            const llmResponse = await generateResponse(currentTask.description, this.contextHistory);
            console.log(`[LLM_RESPONSE] ${llmResponse}`);

            // 2. Parse the response for a tool call.
            const toolCall = this.parseForToolCall(llmResponse);
            let toolResult = "No tool was used. The response was pure text analysis.";

            if (toolCall) {
                if (toolCall.tool === '!missionComplete') {
                    console.log(`[AGENT_SYSTEM] Mission complete: ${toolCall.args.reason}`);
                    return; // End the mission
                }
                // 3. If a tool call exists, execute it.
                console.log(`[AGENT_TOOL_CALL] Executing ${toolCall.tool} with args:`, toolCall.args);
                toolResult = await executeTool(toolCall.tool, toolCall.args);
                console.log(`[AGENT_TOOL_RESULT] ${toolResult}`);
            } else {
                console.log("[AGENT_SYSTEM] No tool call detected. Treating response as analysis.");
            }

            // 4. Update context history.
            this.contextHistory.push({ task: currentTask, result: toolResult });

            // 5. Generate the next task.
            const nextStepPrompt = `Based on the result of the last action, what is the next single, immediate task? If the mission is complete, use the !missionComplete tool.`;
            const nextTaskResponse = await generateResponse(nextStepPrompt, this.contextHistory);

            const nextToolCall = this.parseForToolCall(nextTaskResponse);
            if(nextToolCall && nextToolCall.tool === '!missionComplete') {
                 console.log(`[AGENT_SYSTEM] Mission complete: ${nextToolCall.args.reason}`);
                 return;
            }

            // For simplicity, we treat the next text response as the next task description.
            this.taskQueue.addTask({ id: this.loopCount + 1, description: nextTaskResponse });

            await new Promise(resolve => setTimeout(resolve, CONFIG.AGENT_LOOP_DELAY_MS));
        }

        if (this.loopCount >= CONFIG.AGENT_MAX_LOOPS) {
            console.error('[AGENT_SYSTEM] Maximum loop count reached. Terminating mission to prevent infinite execution.');
        }
    }
}

