/**
 * Performs a single call to the Gemini API with specified parameters.
 * @param {string} fullPrompt The complete prompt including system instructions.
 * @param {object} generationConfig Configuration for the model call (e.g., temperature).
 * @param {boolean} isUnfiltered If true, disables all safety filters.
 * @returns {Promise<string>} The raw text response from the model.
 */
async function geminiCall(fullPrompt, generationConfig, isUnfiltered = false) {
  try {
    const model = genAI.getGenerativeModel({
      model: CONFIG.GEMINI_MODEL_NAME,
      safetySettings: isUnfiltered ? CONFIG.UNFILTERED_SAFETY_SETTINGS : undefined,
    });

    const result = await model.generateContent(fullPrompt, generationConfig);
    const response = await result.response;
    return response.text().trim();
  } catch (error) {
    console.error(`[LLM_HANDLER_ERROR] Gemini API call failed: ${error.message}`);
    return `[ERROR: Generative model failed. Reason: ${error.message}]`;
  }
}

/**
