/**
 * Executes a shell command and returns the output.
 * @param {object} args Arguments for the shell command.
 * @returns {Promise<string>} The stdout or stderr of the command.
 */
async function executeShell(args) {
    if (!args.command) return "Error: 'command' argument is missing.";
    return new Promise((resolve) => {
        exec(args.command, (error, stdout, stderr) => {
            if (error) {
                resolve(`Error: ${error.message}`);
                return;
            }
            if (stderr) {
                resolve(`Stderr: ${stderr}`);
                return;
            }
            resolve(`Stdout: ${stdout}`);
        });
    });
}

/**
 * Fetches content from a URL.
 * @param {object} args Arguments for the web fetch command.
 * @returns {Promise<string>} The content of the URL or an error message.
 */
async function fetchWeb(args) {
    if (!args.url) return "Error: 'url' argument is missing.";
    try {
        const response = await axios.get(args.url, { timeout: 5000 });
        // Return a snippet to avoid overwhelming the context window
        return `Success: Fetched content from ${args.url}. Snippet: ${String(response.data).substring(0, 2000)}`;
    } catch (error) {
        return `Error: Could not fetch URL. ${error.message}`;
    }
}

